"""Feathered, membranous and stone wing creatures; final64/96 pixel anatomy."""
from humanoid import P,BASE
from humanoid_men import pal,human_face

# Wings are authored from articulated roots and tips, with overlapping feather blades.
def feathers(p,root,tip,depth,far=False,fire=False):
 old=p.part;p.at('absolute');sx,sy=root;tx,ty=tip;mx=sx*.48+tx*.52;my=min(sy,ty)-2
 col='R' if fire else 'v';mid='r' if fire else 'a';light='p' if fire else 'A';shine='y' if fire else 'i'
 if far:col='v';mid='a';light='A';shine='i'
 pts=[root,(mx,my),tip]
 for j in range(6):
  u=j/6;bx=tx+(sx-tx)*u;by=ty+(sy-ty)*u
  pts.extend([(bx-2,by+depth*(1-u*.5)),(bx+2,by+depth*(1-u*.5)-3)])
 pts.extend([(sx-3,sy+6),root]);p.poly(pts,col,'o')
 for j in range(6):
  u=j/6;bx=tx+(sx-tx)*u;by=ty+(sy-ty)*u
  p.poly([(bx,by+2),(bx+3,by+2),(bx+3,by+depth*(1-u*.5)-4),(bx-1,by+depth*(1-u*.5)-1),(bx-2,by+depth*(1-u*.5)-3)],mid)
  if not far:p.line([(bx+1,by+4),(bx+1,by+depth*(1-u*.5)-5)],light)
 p.poly([root,(mx,my),tip,(tx+2,ty+depth*.2),(mx-2,my+depth*.3),(sx-2,sy+4)],mid)
 if not far:
  p.line([root,(mx,my+1),(tx+1,ty+1)],shine,2)
  for j in range(5):
   u=(j+1)/6;bx=tx+(sx-tx)*u;by=ty+(sy-ty)*u+depth*.2
   p.poly([(bx-2,by),(bx+1,by-1),(bx+3,by+1),(bx+2,by+4),(bx,by+5),(bx-2,by+2)],light)
   p.line([(bx-1,by+1),(bx+1,by+2)],shine)
 p.part=old

def membrane(p,root,tip,depth,far=False,stone=False):
 old=p.part;p.at('absolute');sx,sy=root;tx,ty=tip;mx=(sx+tx)*.5;my=min(sy,ty)-3
 base='v' if stone or far else 'R';mid='a' if stone else ('r' if far else 'p');light='A' if stone else 'P'
 p.poly([root,(mx,my),tip,(tx+1,ty+depth),(tx+6,ty+depth-4),(mx-2,my+depth+3),(mx+3,my+depth),(sx-5,sy+9)],base,'o')
 p.poly([(sx-2,sy),(mx,my+2),(tx+2,ty+3),(tx+2,ty+depth-3),(mx,my+depth),(sx-4,sy+6)],mid)
 p.poly([(mx+1,my+3),(sx-3,sy+3),(sx-5,sy+7),(mx+2,my+depth-2)],base)
 p.line([root,(mx,my),tip],'A' if stone else 's',2);p.line([root,(mx,my+1),tip],'i' if stone else 'm')
 p.line([(mx,my),(tx+1,ty+depth)],'v' if stone else 'R');p.line([(mx,my),(mx-2,my+depth+3)],'v' if stone else 'R')
 if not far:p.line([(tx+3,ty+4),(tx+3,ty+depth-5)],light);p.line([(mx-2,my+5),(mx-2,my+depth-1)],light)
 if stone:p.line([(mx-4,my+4),(mx-3,my+7),(mx-6,my+9)],'v')
 p.part=old

def wingpose(p,root,near=True,large=False):
 n=p.pose;k=1.5 if large else 1
 tx,ty={'idle_a':(6,12),'idle_b':(7,9),'idle_c':(5,17),'windup':(11,7),'move':(6,10),'attack':(6,25),'recover':(5,21),'hit':(10,29),'dead':(8,48)}[n]
 if not near:tx=56;ty+=4
 return (tx*k,ty*k)

