 p.at('near_leg');p.poly([(35,47),(41,47),(44,51),(41,54),(37,56),(40,56),(44,58),(46,58),(48,60),(42,60),(39,58),(35,60),(31,59),(31,56),(34,53),(32,50)],'a','o');p.poly([(36,48),(40,49),(41,51),(37,53),(34,52)],'A');p.line([(37,49),(39,50)],'i');p.poly([(35,55),(39,55),(41,57),(45,58),(45,60),(40,59),(37,58),(34,59)],'y','o');p.line([(36,56),(39,57)],'Y');p.dots(44,59,['wY'])
 human_face(p,32,9);p.at('head');p.poly([(31,18),(29,14),(29,8),(32,4),(38,3),(44,7),(46,12),(43,15),(39,8),(35,8),(33,12),(33,18),(30,23),(25,28),(24,25),(28,18)],'b','o');p.poly([(31,9),(33,6),(38,5),(42,8),(38,8),(34,10)],'T');p.line([(33,7),(37,6),(40,7)],'y');p.line([(31,13),(31,18),(27,23)],'T');p.eye(41,14);p.line([(40,23),(44,23)],'b');root=p.point(28,29);feathers(p,root,wingpose(p,root),18);return p.im

