def eagle_head(p,x,y,fire=False,scale=1):
 # Final grid coordinates: low sloping forehead, orbital brow, cheek fans and hook.
 old=p.part;p.at('absolute');k=scale
 def pt(a,b):return (x+a*k,y+b*k)
 def poly(ps,col,edge=None):p.poly([pt(a,b) for a,b in ps],col,edge)
 def line(ps,col,width=1):p.line([pt(a,b) for a,b in ps],col,width)
 skin='p' if fire else 'i';shade='r' if fire else 'A';light='y' if fire else 'w'
 poly([(-3,4),(-2,1),(2,-2),(7,-1),(11,2),(12,6),(9,10),(7,13),(4,11),(1,15),(-1,12),(-4,13),(-3,9),(-6,8),(-3,5)],skin,'o');poly([(-1,3),(2,1),(6,1),(9,3),(6,5),(1,6)],light)
 poly([(1,7),(5,6),(8,8),(5,11),(2,10),(0,12),(-2,9)],shade);line([(0,7),(3,9),(2,10)],light)
 poly([(9,4),(14,5),(18,7),(17,10),(15,12),(15,8),(10,8)],'y','o');line([(10,5),(14,6)],'E');p.dot(*pt(14,7),'t')
 if p.pose in ('attack','windup'):
  poly([(8,8),(13,9),(13,12),(8,12)],'R');poly([(8,11),(13,12),(11,14),(8,13)],'y','o')
